"use strict";
const childProcess = require("node:child_process");
const EXIT_SOFTWARE = 70;
let child = null;
let started = false;
let finished = false;
process.once("message", (message) => {
    if (message.kind !== "start" || started)
        process.exit(EXIT_SOFTWARE);
    started = true;
    child = childProcess.spawn(message.command, message.args, {
        cwd: message.cwd,
        env: message.environment,
        detached: false,
        stdio: [message.hasInput ? "pipe" : "ignore", "pipe", "pipe"],
    });
    if (message.hasInput) {
        if (child.stdin == null)
            process.exit(EXIT_SOFTWARE);
        process.stdin.pipe(child.stdin);
    }
    if (child.stdout == null || child.stderr == null)
        process.exit(EXIT_SOFTWARE);
    child.stdout.pipe(process.stdout);
    child.stderr.pipe(process.stderr);
    child.once("exit", (code, signal) => {
        if (process.connected)
            process.send({ kind: "exit", code, signal }, () => { });
    });
    child.once("error", (error) => {
        process.stderr.write(`${error.message}\n`);
        finished = true;
        process.exitCode = EXIT_SOFTWARE;
        process.disconnect?.();
    });
    child.once("close", (code) => {
        finished = true;
        process.exitCode = code ?? EXIT_SOFTWARE;
        process.disconnect?.();
    });
});
process.once("disconnect", () => {
    if (finished)
        return;
    if (child?.pid != null) {
        try {
            process.kill(-process.pid, "SIGKILL");
        }
        catch {
            process.kill(child.pid, "SIGKILL");
        }
        return;
    }
    process.exit();
});
process.send?.({ kind: "ready" });
